/**
 * NODO: "Normalizar entrada"
 * Tipo: Code (n8n-nodes-base.code) — Modo: Run Once for All Items
 *
 * QUE HACE
 *   Toma el mensaje de Telegram y lo convierte en un "estado" limpio que
 *   viaja por el resto del flujo. No consulta nada externo.
 *
 *   1. Extrae el texto del mensaje (text o caption).
 *   2. Busca una URL y/o un DOI dentro del texto.
 *   3. Si el DOI viene embebido en la URL (doi.org/..., ?doi=..., /doi/10.xxxx/...)
 *      lo desentierra y lo limpia de basura de tracking.
 *   4. Construye una url_normalizada estable, que se usa como clave de
 *      deduplicacion cuando la fuente NO tiene DOI.
 *   5. Permite pasar un titulo a mano con la sintaxis:  <url> | <titulo>
 *      (util para PDFs de fabricante o normas donde no hay metadatos).
 *
 * ENTRADA:  item del Telegram Trigger
 * SALIDA:   1 item con el objeto de estado completo
 */

// ---------------------------------------------------------------------------
// Configuracion
// ---------------------------------------------------------------------------

// Zona horaria para el campo fecha_ingreso y para "Consultado el ..." del .bib
const ZONA_HORARIA = 'America/Santiago';

// Parametros de tracking que se eliminan al normalizar la URL (para dedupe)
const PARAMS_BASURA = [
  'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
  'via', 'ref', 'rss', 'fbclid', 'gclid', 'mc_cid', 'mc_eid', 's', 'sk',
];

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------

/**
 * Limpia un DOI candidato: saca puntuacion final, sufijos de plataforma y
 * fragmentos que a veces quedan pegados al copiar el link.
 */
function limpiarDoi(bruto) {
  if (!bruto) return null;
  let doi = String(bruto).trim();

  // A veces llega percent-encoded: 10.1016%2Fj.applthermaleng...
  try {
    if (doi.includes('%2F') || doi.includes('%2f')) doi = decodeURIComponent(doi);
  } catch (e) { /* si el decode falla, seguimos con el original */ }

  // Corta en el primer caracter que nunca forma parte de un DOI
  doi = doi.split(/[\s<>"'()\[\]]/)[0];

  // Corta query string / fragmento
  doi = doi.split('?')[0].split('#')[0];

  // Sufijos que agregan las plataformas al final del path
  doi = doi.replace(/\/(full|abstract|pdf|epdf|meta|html)$/i, '');

  // Puntuacion final tipica de "pegue el link en una frase."
  doi = doi.replace(/[.,;:)\]}]+$/, '');

  // Validacion final del prefijo registrante
  return /^10\.\d{4,9}\/\S+$/.test(doi) ? doi : null;
}

/**
 * Busca un DOI en cualquier texto (mensaje crudo o URL).
 * Cubre los patrones comunes: doi.org/10.x, /doi/10.x, ?doi=10.x, 10.x suelto.
 */
function buscarDoi(texto) {
  if (!texto) return null;

  // Se prueba sobre la cadena cruda y sobre la decodificada, porque hay sitios
  // que pasan el DOI percent-encoded:  ?doi=10.5194%2Fgmd-14-1-2021
  const variantes = [String(texto)];
  try {
    const decodificada = decodeURIComponent(String(texto));
    if (decodificada !== variantes[0]) variantes.push(decodificada);
  } catch (e) { /* URL mal formada: seguimos solo con la cruda */ }

  // Orden importa: primero los patrones anclados, despues el DOI suelto.
  const patrones = [
    /(?:doi\.org\/|dx\.doi\.org\/)(10\.\d{4,9}\/[^\s"'<>]+)/i,
    /[?&]doi=(10\.\d{4,9}\/[^\s"'<>&]+)/i,
    /\/doi\/(?:abs\/|full\/|pdf\/|epdf\/)?(10\.\d{4,9}\/[^\s"'<>]+)/i,
    /\bdoi:\s*(10\.\d{4,9}\/[^\s"'<>]+)/i,
    /(10\.\d{4,9}\/[^\s"'<>]+)/i,
  ];

  for (const re of patrones) {
    for (const v of variantes) {
      const m = v.match(re);
      if (m) {
        const doi = limpiarDoi(m[1]);
        if (doi) return doi;
      }
    }
  }
  return null;
}

/**
 * URL canonica para deduplicar: sin protocolo variable, sin www, sin
 * parametros de tracking, sin barra final, sin fragmento, en minusculas.
 */
function normalizarUrl(url) {
  if (!url) return '';
  try {
    const u = new URL(url);
    u.hash = '';
    u.protocol = 'https:';
    u.hostname = u.hostname.toLowerCase().replace(/^www\./, '');
    // Ojo: "?via%3Dihub" llega como una CLAVE llamada "via=ihub" (el %3D es un '='),
    // asi que no basta con delete('via'): hay que mirar el prefijo de cada clave.
    for (const clave of [...u.searchParams.keys()]) {
      const raiz = clave.toLowerCase().split('=')[0];
      if (PARAMS_BASURA.includes(raiz)) u.searchParams.delete(clave);
    }

    // Ordena los parametros que quedan para que el orden no genere falsos negativos
    const params = [...u.searchParams.entries()].sort((a, b) => a[0].localeCompare(b[0]));
    u.search = '';
    for (const [k, v] of params) u.searchParams.append(k, v);

    let salida = u.toString();
    salida = salida.replace(/\/$/, '');
    return salida.toLowerCase();
  } catch (e) {
    return String(url).trim().toLowerCase().replace(/\/$/, '');
  }
}

// ---------------------------------------------------------------------------
// Proceso
// ---------------------------------------------------------------------------

const entrada = $input.first().json;
const msg = entrada.message || entrada.edited_message || entrada.channel_post || {};
const textoOriginal = String(msg.text || msg.caption || '').trim();

if (!textoOriginal) {
  throw new Error('El mensaje de Telegram no contiene texto ni caption.');
}

// Sintaxis opcional "<url o doi> | <titulo a mano>"
let parteLink = textoOriginal;
let tituloManual = '';
const corte = textoOriginal.indexOf('|');
if (corte !== -1) {
  parteLink = textoOriginal.slice(0, corte).trim();
  tituloManual = textoOriginal.slice(corte + 1).trim();
}

// Primera URL http(s) que aparezca
const mUrl = parteLink.match(/https?:\/\/[^\s<>"']+/i);
let url = mUrl ? mUrl[0].replace(/[.,;:)\]}]+$/, '') : '';

// DOI: primero desde la URL (mas confiable), despues desde el texto completo
const doi = buscarDoi(url) || buscarDoi(parteLink);

// Si mandaron un DOI suelto sin link, construimos la URL de resolucion
let urlDescarga = url;
if (!urlDescarga && doi) urlDescarga = `https://doi.org/${doi}`;

// Pista de titulo: la que se escribio a mano, o el texto si no habia link ni DOI
let tituloHint = tituloManual;
if (!tituloHint && !url && !doi) tituloHint = parteLink;

const ahora = $now.setZone(ZONA_HORARIA);

return [{
  json: {
    // --- trazabilidad ---
    fecha_ingreso: ahora.toFormat('yyyy-LL-dd'),
    fecha_consulta_legible: ahora.toFormat('dd/LL/yyyy'),
    telegram_chat_id: msg.chat ? msg.chat.id : null,
    texto_original: textoOriginal,

    // --- identificadores ---
    doi: doi || '',
    tiene_doi: Boolean(doi),
    url: url || '',
    url_descarga: urlDescarga || '',
    url_normalizada: normalizarUrl(urlDescarga || parteLink),
    hay_url_descarga: Boolean(urlDescarga),

    // --- pistas para Crossref / LLM ---
    titulo_hint: tituloHint || '',

    // Se marca en SI mas adelante si Crossref no devuelve metadatos utilizables
    metadatos_manuales: 'NO',
  },
}];

/**
 * NODO: "Preparar texto"
 * Tipo: Code (n8n-nodes-base.code) — Modo: Run Once for All Items
 *
 * QUE HACE
 *   Recibe lo que haya salido de la descarga (texto de PDF, HTML crudo, o
 *   NADA si no habia URL / la descarga fallo) y produce el texto limpio que
 *   se le pasara al LLM.
 *
 *   Ademas aprovecha el HTML para RESCATAR METADATOS:
 *   muchas editoriales publican <meta name="citation_doi"> y
 *   <meta name="citation_title">, que es la forma mas confiable de sacar el
 *   DOI de un link de ScienceDirect / Springer / Wiley / MDPI, donde el DOI
 *   no aparece en la URL.
 *
 *   NUNCA lanza error: si no hay texto, marca estado_resumen = PENDIENTE y
 *   el flujo sigue igual (requisito: una fuente inaccesible no rompe nada).
 *
 * ENTRADA:  salida de "Extraer texto PDF" | "Extraer texto HTML" | rama sin URL
 * SALIDA:   1 item = estado de "Normalizar entrada" + texto y diagnostico
 */

// ---------------------------------------------------------------------------
// Configuracion
// ---------------------------------------------------------------------------

// Tope de caracteres que se le manda al LLM. ~45k chars ≈ 12k tokens.
const MAX_CHARS = 45000;

// Bajo este umbral asumimos paywall / pagina vacia / captcha.
const MIN_CHARS_UTILES = 600;

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------

/** Decodifica las entidades HTML mas comunes. */
function decodificarEntidades(s) {
  return String(s)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/&#x?([0-9a-f]+);/gi, (_, cod) =>
      String.fromCharCode(parseInt(cod, /^x/i.test(cod) ? 16 : 10)));
}

/** Lee el content de un <meta name="..."> o <meta property="..."> */
function leerMeta(html, nombre) {
  const escapado = nombre.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const patrones = [
    new RegExp(`<meta[^>]+(?:name|property)=["']${escapado}["'][^>]*content=["']([^"']+)["']`, 'i'),
    new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]*(?:name|property)=["']${escapado}["']`, 'i'),
  ];
  for (const re of patrones) {
    const m = html.match(re);
    if (m) return decodificarEntidades(m[1]).trim();
  }
  return '';
}

/** Convierte HTML a texto plano legible. */
function htmlATexto(html) {
  let t = String(html);

  // Fuera todo lo que no es contenido
  t = t.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ');
  t = t.replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ');
  t = t.replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ');
  t = t.replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, ' ');
  t = t.replace(/<nav\b[^>]*>[\s\S]*?<\/nav>/gi, ' ');
  t = t.replace(/<footer\b[^>]*>[\s\S]*?<\/footer>/gi, ' ');
  t = t.replace(/<header\b[^>]*>[\s\S]*?<\/header>/gi, ' ');
  t = t.replace(/<!--[\s\S]*?-->/g, ' ');

  // Saltos de linea donde corresponde semanticamente
  t = t.replace(/<\/(p|div|section|article|li|h[1-6]|tr|br)\s*>/gi, '\n');
  t = t.replace(/<br\s*\/?>/gi, '\n');

  // Fuera el resto de las etiquetas
  t = t.replace(/<[^>]+>/g, ' ');

  t = decodificarEntidades(t);

  // Compacta espacios sin destruir parrafos
  t = t.replace(/[ \t ]+/g, ' ');
  t = t.replace(/\n[ \t]*/g, '\n');
  t = t.replace(/\n{3,}/g, '\n\n');

  return t.trim();
}

/** Reutiliza la logica de limpieza de DOI del nodo 01. */
function limpiarDoi(bruto) {
  if (!bruto) return null;
  let doi = String(bruto).trim();
  try {
    if (doi.includes('%2F') || doi.includes('%2f')) doi = decodeURIComponent(doi);
  } catch (e) { /* noop */ }
  doi = doi.split(/[\s<>"'()\[\]]/)[0];
  doi = doi.split('?')[0].split('#')[0];
  doi = doi.replace(/\/(full|abstract|pdf|epdf|meta|html)$/i, '');
  doi = doi.replace(/[.,;:)\]}]+$/, '');
  return /^10\.\d{4,9}\/\S+$/.test(doi) ? doi : null;
}

// ---------------------------------------------------------------------------
// Proceso
// ---------------------------------------------------------------------------

const estado = { ...$('Normalizar entrada').first().json };
const bruto = $input.first() ? $input.first().json : {};

// De donde puede venir el contenido:
//   - Extract from File / PDF  -> $json.text
//   - Extract from File / Text -> $json.data  (HTML crudo, tal cual se descargo)
//   - rama sin URL             -> nada util
const textoPdf = typeof bruto.text === 'string' ? bruto.text : '';
const textoPlano = typeof bruto.data === 'string' ? bruto.data : '';
const contenido = textoPdf || textoPlano;

const pareceHtml = /<\s*(html|head|body|meta|div|p)\b/i.test(contenido.slice(0, 4000));

let texto = '';
let doiDePagina = null;
let tituloDePagina = '';
let fuenteTexto = 'ninguna';

if (textoPdf) {
  texto = textoPdf;
  fuenteTexto = 'pdf';
} else if (contenido && pareceHtml) {
  fuenteTexto = 'html';

  // --- rescate de metadatos desde las meta tags de la editorial ---
  doiDePagina =
    limpiarDoi(leerMeta(contenido, 'citation_doi')) ||
    limpiarDoi(leerMeta(contenido, 'DC.Identifier')) ||
    limpiarDoi(leerMeta(contenido, 'dc.identifier')) ||
    limpiarDoi(leerMeta(contenido, 'prism.doi')) ||
    null;

  // Ultimo recurso: un doi.org dentro del cuerpo de la pagina
  if (!doiDePagina) {
    const m = contenido.match(/(?:doi\.org\/)(10\.\d{4,9}\/[^\s"'<>]+)/i);
    if (m) doiDePagina = limpiarDoi(m[1]);
  }

  tituloDePagina =
    leerMeta(contenido, 'citation_title') ||
    leerMeta(contenido, 'og:title') ||
    leerMeta(contenido, 'dc.title') ||
    (contenido.match(/<title[^>]*>([\s\S]*?)<\/title>/i)
      ? decodificarEntidades(RegExp.$1).trim()
      : '');

  texto = htmlATexto(contenido);
} else if (contenido) {
  texto = contenido;
  fuenteTexto = 'texto-plano';
}

const longitudBruta = texto.length;
if (longitudBruta > MAX_CHARS) texto = texto.slice(0, MAX_CHARS);

const textoSuficiente = longitudBruta >= MIN_CHARS_UTILES;

// Diagnostico honesto de por que no hay resumen
let motivo = '';
if (!estado.hay_url_descarga) motivo = 'No se recibio URL ni DOI descargable.';
else if (!contenido) motivo = 'La descarga no devolvio contenido (paywall, 403, timeout o binario no soportado).';
else if (!textoSuficiente) motivo = `Texto extraido demasiado corto (${longitudBruta} caracteres); probable paywall o pagina de redireccion.`;

// El DOI de la pagina manda por sobre el que veniamos arrastrando solo si no habia
const doiFinal = estado.doi || doiDePagina || '';

return [{
  json: {
    ...estado,
    doi: doiFinal,
    tiene_doi: Boolean(doiFinal),
    doi_recuperado_de_pagina: Boolean(!estado.doi && doiDePagina),
    titulo_hint: estado.titulo_hint || tituloDePagina || '',
    titulo_pagina: tituloDePagina,

    texto_fuente: texto,
    longitud_texto: longitudBruta,
    fuente_texto: fuenteTexto,
    texto_suficiente: textoSuficiente,
    motivo_sin_texto: motivo,

    // Se confirma en "Consolidar registro"; aqui queda el valor provisorio
    estado_resumen: textoSuficiente ? 'OK' : 'PENDIENTE',
  },
}];

/**
 * NODO: "Elegir candidato Crossref"
 * Tipo: Code (n8n-nodes-base.code) — Modo: Run Once for All Items
 *
 * QUE HACE
 *   Solo corre cuando NO se pudo determinar el DOI ni desde el link ni desde
 *   las meta tags de la pagina. Recibe la respuesta de la busqueda por titulo
 *   en Crossref (/works?query.bibliographic=...) y decide si alguno de los
 *   candidatos es realmente la misma obra.
 *
 *   Es deliberadamente CONSERVADOR: si la similitud de titulo no supera el
 *   umbral, prefiere quedarse sin DOI y marcar metadatos_manuales = SI antes
 *   que asignar un DOI equivocado. Un DOI incorrecto en una memoria de titulo
 *   es peor que un campo vacio.
 *
 * ENTRADA:  respuesta JSON de Crossref search (o item de error si fallo)
 * SALIDA:   1 item = estado + doi (si hubo match confiable)
 */

// ---------------------------------------------------------------------------
// Configuracion
// ---------------------------------------------------------------------------

// Similitud minima de titulo (0..1) para aceptar el DOI automaticamente.
// 0.72 es estricto a proposito. Bajalo a ~0.60 si ves demasiados falsos negativos.
const UMBRAL_SIMILITUD = 0.72;

// Palabras que no aportan a la comparacion de titulos
const VACIAS = new Set([
  'a', 'an', 'the', 'of', 'on', 'in', 'for', 'and', 'or', 'to', 'with', 'by',
  'from', 'at', 'as', 'is', 'are', 'using', 'via',
  'el', 'la', 'los', 'las', 'un', 'una', 'de', 'del', 'y', 'o', 'en', 'para',
  'con', 'por', 'sobre', 'mediante',
]);

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------

/** Minusculas, sin tildes, sin puntuacion, sin etiquetas HTML. */
function normalizarTexto(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, ' ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenizar(s) {
  return normalizarTexto(s).split(' ').filter((w) => w.length > 2 && !VACIAS.has(w));
}

/**
 * Similitud de titulos sobre bolsas de palabras significativas.
 *
 * Combina dos medidas porque cada una falla en un caso distinto:
 *
 *   - Sorensen-Dice: buena en general, pero castiga fuerte la asimetria de
 *     largo. El titulo que uno anota a mano ("Performance intensification of
 *     regeneration process") suele ser un PREFIJO del titulo completo de
 *     Crossref, y Dice lo deja bajo el umbral aunque sea el mismo paper.
 *
 *   - Coeficiente de contencion (|A∩B| / min(|A|,|B|)): resuelve justamente
 *     ese caso, pero por si solo es demasiado permisivo con titulos cortos
 *     ("energia solar" calzaria con cualquier paper que use ambas palabras).
 *
 * Por eso la contencion solo se toma en cuenta si hay al menos MIN_COMUNES
 * palabras significativas compartidas, y se le aplica una pequena penalizacion
 * para que nunca puntue mas alto que una coincidencia realmente exacta.
 */
const MIN_COMUNES = 3;

function similitud(a, b) {
  const A = new Set(tokenizar(a));
  const B = new Set(tokenizar(b));
  if (A.size === 0 || B.size === 0) return 0;

  let comunes = 0;
  for (const w of A) if (B.has(w)) comunes++;

  const dice = (2 * comunes) / (A.size + B.size);
  if (comunes < MIN_COMUNES) return dice;

  const contencion = comunes / Math.min(A.size, B.size);
  return Math.max(dice, contencion * 0.95);
}

// ---------------------------------------------------------------------------
// Proceso
// ---------------------------------------------------------------------------

const estado = { ...$('Preparar texto').first().json };
const respuesta = $input.first() ? $input.first().json : {};

// Referencia contra la cual comparamos: el titulo que pusimos a mano,
// el <title> de la pagina, o el propio texto del mensaje.
const referencia = estado.titulo_hint || estado.titulo_pagina || estado.texto_original || '';

const candidatos = (respuesta &&
  respuesta.message &&
  Array.isArray(respuesta.message.items))
  ? respuesta.message.items
  : [];

let mejor = null;
let mejorPuntaje = 0;

for (const c of candidatos) {
  const tituloCandidato = Array.isArray(c.title) ? c.title.join(' ') : String(c.title || '');
  if (!tituloCandidato) continue;

  const p = similitud(referencia, tituloCandidato);
  if (p > mejorPuntaje) {
    mejorPuntaje = p;
    mejor = c;
  }
}

const aceptado = Boolean(mejor && mejorPuntaje >= UMBRAL_SIMILITUD && mejor.DOI);

return [{
  json: {
    ...estado,
    doi: aceptado ? String(mejor.DOI).toLowerCase() : '',
    tiene_doi: aceptado,
    doi_recuperado_por_busqueda: aceptado,

    // Trazabilidad para poder auditar despues por que se eligio (o no) un DOI
    crossref_busqueda_candidatos: candidatos.length,
    crossref_busqueda_puntaje: Number(mejorPuntaje.toFixed(3)),
    crossref_busqueda_titulo_elegido: mejor
      ? (Array.isArray(mejor.title) ? mejor.title.join(' ') : String(mejor.title || ''))
      : '',
    crossref_busqueda_umbral: UMBRAL_SIMILITUD,
  },
}];

/**
 * NODO: "Normalizar metadatos"
 * Tipo: Code (n8n-nodes-base.code) — Modo: Run Once for All Items
 *
 * QUE HACE
 *   Traduce la respuesta cruda de Crossref (/works/{doi}) a un conjunto plano
 *   de campos bibliograficos, y mapea el `type` de Crossref al tipo de entrada
 *   BibTeX correcto.
 *
 *   *** ESTE NODO ES LA UNICA FUENTE DE VERDAD BIBLIOGRAFICA. ***
 *   Autores, anio, revista, editorial, volumen, numero, paginas y tipo salen
 *   exclusivamente de aqui. El LLM no toca ninguno de estos campos.
 *
 *   Si no hubo DOI o Crossref no respondio, igual emite un registro valido
 *   con metadatos_manuales = SI, para que la fila quede marcada para revision.
 *
 * ENTRADA:  respuesta de "Crossref metadatos" (o rama sin DOI)
 * SALIDA:   1 item = estado + campos bibliograficos normalizados
 */

// ---------------------------------------------------------------------------
// Mapa Crossref type -> tipo de entrada BibTeX
// ---------------------------------------------------------------------------
const MAPA_TIPO_BIBTEX = {
  'journal-article': 'article',
  'journal-issue': 'misc',
  'journal-volume': 'misc',
  'journal': 'misc',

  'book': 'book',
  'monograph': 'book',
  'edited-book': 'book',
  'reference-book': 'book',

  'book-chapter': 'incollection',
  'book-section': 'incollection',
  'book-part': 'incollection',
  'book-track': 'incollection',
  'reference-entry': 'incollection',

  'proceedings-article': 'inproceedings',
  'proceedings': 'proceedings',

  'report': 'techreport',
  'report-component': 'techreport',
  'report-series': 'techreport',
  'standard': 'techreport',      // normas ISO / NCh / ASME
  'standard-series': 'techreport',

  'dissertation': 'phdthesis',

  'posted-content': 'misc',      // preprints (arXiv, SSRN, bioRxiv...)
  'dataset': 'misc',
  'component': 'misc',
  'peer-review': 'misc',
  'other': 'misc',
};

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------

/** Crossref entrega titulos con etiquetas MathML/HTML incrustadas. */
function limpiarCampo(s) {
  return String(s == null ? '' : s)
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** Toma el primer elemento util de un campo que Crossref entrega como array. */
function primero(v) {
  if (Array.isArray(v)) return limpiarCampo(v.find((x) => x != null && String(x).trim() !== '') || '');
  return limpiarCampo(v);
}

/**
 * Normaliza la lista de autores.
 * Distingue personas ({given, family}) de organizaciones ({name}), porque en
 * BibTeX las organizaciones se protegen con llaves para que BibTeX no las
 * parta como "Apellido, Nombre".
 */
function normalizarAutores(lista) {
  if (!Array.isArray(lista)) return [];
  return lista
    .map((a) => {
      if (a && a.name) {
        return { tipo: 'organizacion', nombre: limpiarCampo(a.name), apellido: limpiarCampo(a.name), given: '' };
      }
      const family = limpiarCampo(a && a.family);
      const given = limpiarCampo(a && a.given);
      if (!family && !given) return null;
      return {
        tipo: 'persona',
        apellido: family || given,
        given: family ? given : '',
        nombre: [given, family].filter(Boolean).join(' '),
      };
    })
    .filter(Boolean);
}

/** Crossref guarda las fechas como {'date-parts': [[aaaa, mm, dd]]}. */
function extraerAnio(...candidatos) {
  for (const c of candidatos) {
    const partes = c && c['date-parts'] && c['date-parts'][0];
    if (Array.isArray(partes) && partes[0]) return String(partes[0]);
  }
  return '';
}

// ---------------------------------------------------------------------------
// Proceso
// ---------------------------------------------------------------------------

const estado = { ...$('Preparar texto').first().json };

// El DOI puede haber sido resuelto despues de "Preparar texto" (rama de busqueda
// por titulo). "Unificar DOI" deja el valor vigente en el item que entra aqui.
let doiVigente = estado.doi || '';

const bruto = $input.first() ? $input.first().json : {};
const cr = (bruto && bruto.message && typeof bruto.message === 'object') ? bruto.message : null;

// Si venimos de la rama con DOI, ese item puede traer el estado actualizado
if (!doiVigente && bruto && bruto.doi) doiVigente = String(bruto.doi);
if (cr && cr.DOI) doiVigente = String(cr.DOI).toLowerCase();

let meta;

if (cr) {
  // --------------------------- CON metadatos Crossref ---------------------
  const tipoCrossref = String(cr.type || 'other');
  const autores = normalizarAutores(cr.author);
  const editores = normalizarAutores(cr.editor);

  const anio = extraerAnio(cr.issued, cr['published-print'], cr['published-online'], cr.created);

  // Institucion (tesis, informes tecnicos y normas)
  let institucion = '';
  if (Array.isArray(cr.institution) && cr.institution.length) {
    institucion = limpiarCampo(cr.institution[0].name || cr.institution[0]);
  }

  // Nombre del evento (congresos)
  const evento = cr.event ? limpiarCampo(cr.event.name) : '';

  meta = {
    titulo: primero(cr.title) || estado.titulo_hint || '(sin titulo)',
    subtitulo: primero(cr.subtitle),
    autores,
    editores,
    autores_texto: autores.map((a) => a.nombre).join('; '),
    anio,
    publicacion: primero(cr['container-title']) || evento || institucion || limpiarCampo(cr.publisher),
    publicacion_corta: primero(cr['short-container-title']),
    editorial: limpiarCampo(cr.publisher),
    institucion,
    evento,
    volumen: limpiarCampo(cr.volume),
    numero: limpiarCampo(cr.issue),
    paginas: limpiarCampo(cr.page || cr['article-number']),
    issn: Array.isArray(cr.ISSN) ? cr.ISSN[0] : limpiarCampo(cr.ISSN),
    isbn: Array.isArray(cr.ISBN) ? cr.ISBN[0] : limpiarCampo(cr.ISBN),
    tipo_crossref: tipoCrossref,
    tipo_bibtex: MAPA_TIPO_BIBTEX[tipoCrossref] || 'misc',
    es_preprint: tipoCrossref === 'posted-content',
    url_publicada: limpiarCampo(cr.URL) || (doiVigente ? `https://doi.org/${doiVigente}` : ''),
    metadatos_manuales: 'NO',
    origen_metadatos: 'crossref',
  };
} else {
  // ------------------- SIN metadatos: pagina web, norma, catalogo ---------
  // No inventamos nada. Solo lo que efectivamente sabemos.
  meta = {
    titulo: estado.titulo_hint || estado.titulo_pagina || estado.url || '(sin titulo)',
    subtitulo: '',
    autores: [],
    editores: [],
    autores_texto: '',
    anio: '',
    publicacion: '',
    publicacion_corta: '',
    editorial: '',
    institucion: '',
    evento: '',
    volumen: '',
    numero: '',
    paginas: '',
    issn: '',
    isbn: '',
    tipo_crossref: 'web',
    tipo_bibtex: 'misc',
    es_preprint: false,
    url_publicada: estado.url || estado.url_descarga || '',
    metadatos_manuales: 'SI',
    origen_metadatos: doiVigente ? 'crossref-sin-respuesta' : 'sin-doi',
  };
}

// Si Crossref respondio pero sin autores ni anio, tampoco sirve para citar solo
if (meta.origen_metadatos === 'crossref' && meta.autores.length === 0 && !meta.anio) {
  meta.metadatos_manuales = 'SI';
}

return [{
  json: {
    ...estado,
    ...meta,
    doi: doiVigente,
    tiene_doi: Boolean(doiVigente),
    url_final: estado.url || meta.url_publicada || estado.url_descarga || '',
  },
}];

/**
 * NODO: "Dedupe y citation key"
 * Tipo: Code (n8n-nodes-base.code) — Modo: Run Once for All Items
 *
 * QUE HACE
 *   Recibe TODAS las filas actuales del consolidado (Google Sheets) y:
 *
 *   1. DEDUPLICA. Si el DOI ya esta registrado -> duplicado.
 *      Si no hay DOI, compara la url_normalizada -> duplicado.
 *      Esto es lo que hace el flujo idempotente: reenviar el mismo link no
 *      escribe nada nuevo en ningun lado.
 *
 *   2. GENERA LA CITATION KEY con la convencion apellidoAAAApalabraclave,
 *      todo en minusculas, sin tildes ni caracteres especiales, y le agrega
 *      sufijo b, c, d... si esa key ya existe en el consolidado.
 *
 *   Se ejecuta ANTES de cualquier escritura y antes de gastar tokens de LLM.
 *
 * ENTRADA:  filas de "Leer consolidado" (puede venir 1 item vacio si la
 *           planilla esta recien creada; el nodo tiene alwaysOutputData=true)
 * SALIDA:   1 item = estado + { duplicado, citation_key }
 */

// ---------------------------------------------------------------------------
// Configuracion
// ---------------------------------------------------------------------------

// Palabras que no sirven como "palabraclave" de la citation key
const VACIAS = new Set([
  'a', 'an', 'the', 'of', 'on', 'in', 'for', 'and', 'or', 'to', 'with', 'by',
  'from', 'at', 'as', 'is', 'are', 'was', 'were', 'using', 'via', 'about',
  'study', 'analysis', 'new', 'towards', 'toward',
  'el', 'la', 'los', 'las', 'un', 'una', 'unos', 'unas', 'de', 'del', 'y', 'o',
  'en', 'para', 'con', 'por', 'sobre', 'mediante', 'estudio', 'analisis',
]);

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------

/**
 * Deja solo [a-z0-9]: minusculas, sin tildes, sin ñ, sin guiones.
 * "Muñoz-Peña" -> "munozpena" ; "Ávila" -> "avila"
 */
function ascii(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')   // quita los diacriticos ya separados
    .replace(/ø/gi, 'o')
    .replace(/æ/gi, 'ae')
    .replace(/ß/gi, 'ss')
    .replace(/đ|ð/gi, 'd')
    .replace(/ł/gi, 'l')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

/** Primera palabra significativa del titulo, en ascii. */
function palabraClave(titulo) {
  const palabras = String(titulo || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean);

  const util = palabras.find((w) => w.length > 3 && !VACIAS.has(w));
  return ascii(util || palabras[0] || 'ref').slice(0, 20);
}

/**
 * Sufijo alfabetico al estilo BibTeX: '', 'b', 'c', ... 'z', 'aa', 'ab'...
 * (el indice 0 no lleva sufijo, que es la key "limpia")
 */
function sufijo(indice) {
  if (indice <= 0) return '';
  let n = indice;            // 1 -> b, 2 -> c ...
  let s = '';
  n += 1;                    // desplaza para que 1 caiga en 'b'
  while (n > 0) {
    const r = (n - 1) % 26;
    s = String.fromCharCode(97 + r) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

/** Normalizacion de URL identica a la del nodo 01, para comparar peras con peras. */
function normalizarUrl(url) {
  if (!url) return '';
  const PARAMS_BASURA = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term',
    'utm_content', 'via', 'ref', 'rss', 'fbclid', 'gclid', 'mc_cid', 'mc_eid', 's', 'sk'];
  try {
    const u = new URL(url);
    u.hash = '';
    u.protocol = 'https:';
    u.hostname = u.hostname.toLowerCase().replace(/^www\./, '');
    // Ojo: "?via%3Dihub" llega como una CLAVE llamada "via=ihub" (el %3D es un '='),
    // asi que no basta con delete('via'): hay que mirar el prefijo de cada clave.
    for (const clave of [...u.searchParams.keys()]) {
      const raiz = clave.toLowerCase().split('=')[0];
      if (PARAMS_BASURA.includes(raiz)) u.searchParams.delete(clave);
    }
    const params = [...u.searchParams.entries()].sort((a, b) => a[0].localeCompare(b[0]));
    u.search = '';
    for (const [k, v] of params) u.searchParams.append(k, v);
    return u.toString().replace(/\/$/, '').toLowerCase();
  } catch (e) {
    return String(url).trim().toLowerCase().replace(/\/$/, '');
  }
}

// ---------------------------------------------------------------------------
// Proceso
// ---------------------------------------------------------------------------

const estado = { ...$('Normalizar metadatos').first().json };

// Filas existentes. Si la planilla esta vacia llega un unico item {} por
// alwaysOutputData, por eso filtramos por citation_key presente.
const filas = $input.all()
  .map((i) => i.json || {})
  .filter((f) => f && String(f.citation_key || '').trim() !== '');

const doiNuevo = String(estado.doi || '').trim().toLowerCase();
const urlNueva = estado.url_normalizada || normalizarUrl(estado.url_final || estado.url);

// --- 1. Deteccion de duplicado -------------------------------------------
let filaDuplicada = null;

if (doiNuevo) {
  filaDuplicada = filas.find(
    (f) => String(f.doi || '').trim().toLowerCase() === doiNuevo,
  ) || null;
}

if (!filaDuplicada && urlNueva) {
  filaDuplicada = filas.find(
    (f) => normalizarUrl(f.url || '') === urlNueva,
  ) || null;
}

// --- 2. Citation key ------------------------------------------------------
const primerAutor = (estado.autores && estado.autores.length)
  ? estado.autores[0]
  : ((estado.editores && estado.editores.length) ? estado.editores[0] : null);

let base = '';
if (primerAutor) {
  base = ascii(primerAutor.apellido);
} else if (estado.institucion) {
  base = ascii(estado.institucion).slice(0, 14);
} else if (estado.editorial) {
  base = ascii(estado.editorial).slice(0, 14);
} else {
  // ultimo recurso: el dominio del sitio ("nch", "sciencedirect", "skf"...)
  try {
    base = ascii(new URL(estado.url_final || estado.url).hostname.replace(/^www\./, '').split('.')[0]);
  } catch (e) {
    base = 'anon';
  }
}
if (!base) base = 'anon';

// Anio: 'sf' = sin fecha (convencion bibliografica en espanol)
const anio = /^\d{4}$/.test(String(estado.anio || '')) ? String(estado.anio) : 'sf';

const keyBase = `${base}${anio}${palabraClave(estado.titulo)}`;

// Colisiones contra las keys que YA existen en el consolidado
const keysExistentes = new Set(filas.map((f) => String(f.citation_key || '').trim().toLowerCase()));

let indice = 0;
let citationKey = keyBase;
while (keysExistentes.has(citationKey.toLowerCase())) {
  indice += 1;
  citationKey = keyBase + sufijo(indice);
  if (indice > 200) break;   // salvaguarda contra bucle infinito
}

return [{
  json: {
    ...estado,

    duplicado: Boolean(filaDuplicada),
    citation_key_existente: filaDuplicada ? String(filaDuplicada.citation_key || '') : '',
    fila_duplicada_titulo: filaDuplicada ? String(filaDuplicada.titulo || '') : '',
    fila_duplicada_link_nota: filaDuplicada ? String(filaDuplicada.link_nota || '') : '',

    citation_key: citationKey,
    citation_key_base: keyBase,
    citation_key_sufijo_aplicado: indice > 0,

    url_normalizada: urlNueva,
    filas_revisadas: filas.length,
  },
}];

